source_edits.before:
.ok_or_else(|| {
    session.early_dead.set();
    anyhow::anyhow!("timeout waiting for tunnel open response")
})?;

source_edits.after:
.ok_or_else(|| {
    // Slipstream: a destination open timeout is not a mux failure.
    // Drop only this new stream; existing tunnels remain usable.
    // Transport death is still handled by mux liveness/proxy_loop.
    anyhow::anyhow!("timeout waiting for tunnel open response")
})?;

#[cfg(test)]
mod slipstream_isolation_tests {
    use super::*;
    use tokio::io::{AsyncReadExt, AsyncWriteExt};

    #[tokio::test]
    async fn stalled_new_tunnel_preserves_existing_stream() {
        let (a, b) = tokio::io::duplex(65536);
        let (ar, aw) = tokio::io::split(a);
        let (br, bw) = tokio::io::split(b);
        let mux = Arc::new(PicoMux::new(ar, aw));
        let peer = PicoMux::new(br, bw);
        let (existing, accepted) = tokio::join!(mux.open(b"existing"), peer.accept());
        let mut existing = existing.unwrap();
        let mut accepted = accepted.unwrap();
        let (accounting, _accounting_loop) = bw_accounting_pair();
        let session = Arc::new(ConnectedSession {
            worker_id: 0, exit: "fixture".into(), bridge: "fixture".into(),
            mux, accounting, pending_opens: AtomicUsize::new(0),
            early_dead: Arc::new(ManualResetEvent::new(false)),
        });
        let ctx = AnyCtx::new(serde_json::from_value::<Config>(
            serde_json::json!({"exit_constraint":"auto"})).unwrap());
        let opening = open_tunnel_on_session(&ctx, &session,
            RichTunnelCommand { protocol:"tcp".into(), host:"fixture.invalid:443".into() });
        // Keep the accepted new stream alive but never send its open response.
        let holding_peer = async { let _stalled = peer.accept().await.unwrap();
            tokio::time::sleep(Duration::from_secs(11)).await; };
        let (result, ()) = tokio::join!(opening, holding_peer);
        assert!(result.unwrap_err().to_string().contains("timeout waiting"));
        assert!(!session.early_dead.is_set(), "a single tunnel timeout killed the shared session");
        assert_eq!(session.pending_opens.load(Ordering::Relaxed), 0);
        accepted.write_all(b"still alive").await.unwrap();
        let mut bytes = [0u8; 11];
        tokio::time::timeout(Duration::from_secs(2), existing.read_exact(&mut bytes)).await.unwrap().unwrap();
        assert_eq!(&bytes, b"still alive");
    }
}

